const link = (url, text, lang = 'en') =>
  `<a href='${url}${lang === 'ar' ? '' : '?lang=' + lang}' class='font-bold text-brand-blue underline decoration-from-font underline-offset-2 hover:text-brand-orange'>${text}</a>`;

const now = new Date();
function futureDate(daysFromNow) {
  const d = new Date(now);
  d.setDate(d.getDate() + daysFromNow);
  return d.toISOString().split('T')[0];
}

